// Oracle for core/config_parser (ConfigParser: parsing, @include, overrides, used-key tracking and all
// getters, with byte-exact error texts). Links against the unmodified upstream sources of KataGo v1.16.5.
// The Rust mirror is crates/katago-core/tests/config_parser.rs.
//
// Both sides run the same script, fixtures/upstream-v1.16.5/unit/oracle/config_parser_ops.txt (generated by
// config_parser_ops_gen.py next to it). One op per line, tab-separated fields, C-escaped (\n \r \t \\ \xHH)
// strings; '#' lines and empty lines are ignored. Ops: file, newempty, new, newfile, newkvs, copy, init_in,
// init_file, init_kvs, info, get*, contains, containsany, firstfail, firstempty, overridekey, overridekeys,
// overridekeysm, overridekeysfile, parsecomma, markused, markprefix, unsetused, warn, alias (see run()).
// "file" ops write real files under a scratch directory the oracle creates and chdirs into, so the include
// paths in error texts are relative (the Rust side serves the same names from memory through
// ConfigParser::set_include_reader). Output: one line per op, "<lineno> <op> <result>", where the result is
// "ok ..." or "err <ConfigParsingError|IOError|StringError> [<what, escaped>]". Floats and doubles are printed
// as the hex digits of their bits. warnUnusedKeys is called with a NULL logger (the Rust side logs through the
// `log` crate instead).
//
// Build (from the repo root, output outside the repo; upstream untouched; asserts on):
//   U=upstream/KataGo/cpp; g++ -std=c++17 -O1 -I$U -isystem $U/external/filesystem-1.5.8/include \
//     -o /tmp/config_parser_oracle fixtures/upstream-v1.16.5/unit/oracle/config_parser.cpp \
//     $U/core/config_parser.cpp $U/core/fileutils.cpp $U/core/global.cpp $U/core/sha2.cpp $U/core/hash.cpp \
//     $U/core/rand.cpp $U/core/md5.cpp $U/core/timer.cpp $U/core/test.cpp $U/core/bsearch.cpp \
//     $U/core/logger.cpp $U/core/datetime.cpp $U/core/makedir.cpp $U/core/base64.cpp -lpthread -lz
// Run (from the repo root):
//   /tmp/config_parser_oracle fixtures/upstream-v1.16.5/unit/oracle/config_parser_ops.txt \
//     > fixtures/upstream-v1.16.5/unit/oracle/config_parser.txt
// Generated with g++ (GCC) 16.2.1 / glibc 2.44 on x86_64 Linux.
#include <cfloat>
#include <climits>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iostream>
#include <map>
#include <set>
#include <sstream>
#include <string>
#include <unistd.h>
#include <vector>
#include <sys/stat.h>
#include "core/config_parser.h"
#include "core/global.h"
using namespace std;

static string esc(const string& s) {
  string r;
  char b[8];
  for(unsigned char c : s) {
    if(c == '\\') r += "\\\\";
    else if(c == '\n') r += "\\n";
    else if(c == '\r') r += "\\r";
    else if(c == '\t') r += "\\t";
    else if(c < 0x20 || c >= 0x7f) { snprintf(b, sizeof(b), "\\x%02x", c); r += b; }
    else r += (char)c;
  }
  return r;
}

static string unesc(const string& s) {
  string r;
  for(size_t i = 0; i < s.size(); i++) {
    if(s[i] != '\\') { r += s[i]; continue; }
    i++;
    char c = s[i];
    if(c == 'n') r += '\n';
    else if(c == 'r') r += '\r';
    else if(c == 't') r += '\t';
    else if(c == '\\') r += '\\';
    else if(c == 'x') { r += (char)stoi(s.substr(i + 1, 2), nullptr, 16); i += 2; }
    else { cerr << "bad escape in script: " << s << endl; exit(1); }
  }
  return r;
}

static string q(const string& s) { return "[" + esc(s) + "]"; }

static string dbits(double x) {
  uint64_t u; memcpy(&u, &x, 8);
  char b[17]; snprintf(b, sizeof(b), "%016llX", (unsigned long long)u);
  return string(b);
}
static string fbits(float x) {
  uint32_t u; memcpy(&u, &x, 4);
  char b[9]; snprintf(b, sizeof(b), "%08X", u);
  return string(b);
}

static vector<string> splitOn(const string& s, char d) {
  vector<string> r;
  if(s.empty()) return r;
  string cur;
  for(char c : s) {
    if(c == d) { r.push_back(cur); cur.clear(); }
    else cur += c;
  }
  r.push_back(cur);
  return r;
}

static map<string, string> parseKvs(const string& s) {
  map<string, string> m;
  for(const string& item : splitOn(s, ',')) {
    size_t p = item.find('=');
    m[item.substr(0, p)] = p == string::npos ? string() : item.substr(p + 1);
  }
  return m;
}

static set<string> toSet(const string& s) {
  vector<string> v = splitOn(s, ',');
  return set<string>(v.begin(), v.end());
}

static int parseInt(const string& s) {
  if(s == "lowest") return INT_MIN;
  if(s == "max") return INT_MAX;
  return (int)stoll(s);
}
static int64_t parseInt64(const string& s) {
  if(s == "lowest") return INT64_MIN;
  if(s == "max") return INT64_MAX;
  return (int64_t)stoll(s);
}
static uint64_t parseUInt64(const string& s) {
  if(s == "lowest") return 0;
  if(s == "max") return UINT64_MAX;
  return (uint64_t)stoull(s);
}
static float parseFloat(const string& s) {
  if(s == "lowest") return -FLT_MAX;
  if(s == "max") return FLT_MAX;
  uint32_t u = (uint32_t)stoul(s, nullptr, 16);
  float x; memcpy(&x, &u, 4);
  return x;
}
static double parseDouble(const string& s) {
  if(s == "lowest") return -DBL_MAX;
  if(s == "max") return DBL_MAX;
  uint64_t u = stoull(s, nullptr, 16);
  double x; memcpy(&x, &u, 8);
  return x;
}

static string info(const ConfigParser& c) {
  string unused;
  vector<string> u = c.unusedKeys();
  for(size_t i = 0; i < u.size(); i++) {
    if(i > 0) unused += ",";
    unused += u[i];
  }
  return "file=" + q(c.getFileName()) + " contents=" + q(c.getContents()) + " kv=" + q(c.getAllKeyVals()) + " unused=" + q(unused);
}

static void writeFile(const string& path, const string& content) {
  size_t slash = path.find_last_of('/');
  if(slash != string::npos) {
    string dir;
    for(const string& part : splitOn(path.substr(0, slash), '/')) {
      dir += part + "/";
      mkdir(dir.c_str(), 0755);
    }
  }
  ofstream f(path, ios::binary);
  f << content;
}

static void rmTree(const string& dir) {
  string cmd = "rm -rf '" + dir + "'";
  if(system(cmd.c_str()) != 0) cerr << "cleanup failed: " << dir << endl;
}

int main(int argc, char** argv) {
  if(argc < 2) { cerr << "usage: config_parser_oracle <ops.txt>" << endl; return 1; }
  ifstream script(argv[1], ios::binary);
  if(!script.good()) { cerr << "cannot open " << argv[1] << endl; return 1; }

  char tmpl[] = "/tmp/config_parser_oracle_XXXXXX";
  string scratch = mkdtemp(tmpl);
  if(chdir(scratch.c_str()) != 0) { cerr << "chdir failed" << endl; return 1; }

  map<string, ConfigParser*> cfgs;
  string line;
  int lineno = 0;
  int nops = 0;
  while(getline(script, line)) {
    lineno++;
    if(line.empty() || line[0] == '#') continue;
    vector<string> f;
    {
      string cur;
      for(char c : line) {
        if(c == '\t') { f.push_back(cur); cur.clear(); }
        else cur += c;
      }
      f.push_back(cur);
    }
    for(size_t i = 1; i < f.size(); i++) f[i] = unesc(f[i]);
    const string& op = f[0];
    nops++;
    cout << lineno << " " << op;
    if(f.size() > 1 && op != "file" && op != "parsecomma" && op != "containsany" && op != "firstfail" && op != "firstempty") cout << " " << f[1];
    cout << " ";
    ostringstream r;
    try {
      auto cfg = [&](const string& name) -> ConfigParser& {
        auto it = cfgs.find(name);
        if(it == cfgs.end()) { cerr << "script error line " << lineno << ": no parser " << name << endl; exit(1); }
        return *it->second;
      };
      auto put = [&](const string& name, ConfigParser* c) {
        auto it = cfgs.find(name);
        if(it != cfgs.end()) delete it->second;
        cfgs[name] = c;
        r << "ok " << info(*c);
      };
      if(op == "file") {
        writeFile(f[1], f[2]);
        r << "ok";
      }
      else if(op == "newempty") {
        put(f[1], new ConfigParser(f[2] == "1", f[3] == "1"));
      }
      else if(op == "new") {
        istringstream in(f[4]);
        put(f[1], new ConfigParser(in, f[2] == "1", f[3] == "1"));
      }
      else if(op == "newfile") {
        put(f[1], new ConfigParser(f[4], f[2] == "1", f[3] == "1"));
      }
      else if(op == "newkvs") {
        put(f[1], new ConfigParser(parseKvs(f[2])));
      }
      else if(op == "copy") {
        put(f[1], new ConfigParser(cfg(f[2])));
      }
      else if(op == "init_in") {
        istringstream in(f[2]);
        cfg(f[1]).initialize(in);
        r << "ok " << info(cfg(f[1]));
      }
      else if(op == "init_file") {
        cfg(f[1]).initialize(f[2]);
        r << "ok " << info(cfg(f[1]));
      }
      else if(op == "init_kvs") {
        cfg(f[1]).initialize(parseKvs(f[2]));
        r << "ok " << info(cfg(f[1]));
      }
      else if(op == "info") {
        r << "ok " << info(cfg(f[1]));
      }
      else if(op == "getstring") {
        r << "ok " << q(cfg(f[1]).getString(f[2]));
      }
      else if(op == "getstringp") {
        r << "ok " << q(cfg(f[1]).getString(f[2], toSet(f[3])));
      }
      else if(op == "getstrings" || op == "getstringsnet" || op == "getstringsp") {
        vector<string> v = op == "getstrings" ? cfg(f[1]).getStrings(f[2])
          : op == "getstringsnet" ? cfg(f[1]).getStringsNonEmptyTrim(f[2])
          : cfg(f[1]).getStrings(f[2], toSet(f[3]));
        r << "ok " << v.size();
        for(const string& s : v) r << " " << q(s);
      }
      else if(op == "getbool") {
        r << "ok " << (cfg(f[1]).getBool(f[2]) ? 1 : 0);
      }
      else if(op == "getbools") {
        vector<bool> v = cfg(f[1]).getBools(f[2]);
        r << "ok " << v.size();
        for(bool b : v) r << " " << (b ? 1 : 0);
      }
      else if(op == "getenabled") {
        r << "ok " << cfg(f[1]).getEnabled(f[2]).toString();
      }
      else if(op == "getint") {
        r << "ok " << cfg(f[1]).getInt(f[2], parseInt(f[3]), parseInt(f[4]));
      }
      else if(op == "getints") {
        vector<int> v = cfg(f[1]).getInts(f[2], parseInt(f[3]), parseInt(f[4]));
        r << "ok " << v.size();
        for(int x : v) r << " " << x;
      }
      else if(op == "getint64") {
        r << "ok " << cfg(f[1]).getInt64(f[2], parseInt64(f[3]), parseInt64(f[4]));
      }
      else if(op == "getint64s") {
        vector<int64_t> v = cfg(f[1]).getInt64s(f[2], parseInt64(f[3]), parseInt64(f[4]));
        r << "ok " << v.size();
        for(int64_t x : v) r << " " << x;
      }
      else if(op == "getuint64") {
        r << "ok " << cfg(f[1]).getUInt64(f[2], parseUInt64(f[3]), parseUInt64(f[4]));
      }
      else if(op == "getuint64s") {
        vector<uint64_t> v = cfg(f[1]).getUInt64s(f[2], parseUInt64(f[3]), parseUInt64(f[4]));
        r << "ok " << v.size();
        for(uint64_t x : v) r << " " << x;
      }
      else if(op == "getfloat") {
        r << "ok " << fbits(cfg(f[1]).getFloat(f[2], parseFloat(f[3]), parseFloat(f[4])));
      }
      else if(op == "getfloats") {
        vector<float> v = cfg(f[1]).getFloats(f[2], parseFloat(f[3]), parseFloat(f[4]));
        r << "ok " << v.size();
        for(float x : v) r << " " << fbits(x);
      }
      else if(op == "getdouble") {
        r << "ok " << dbits(cfg(f[1]).getDouble(f[2], parseDouble(f[3]), parseDouble(f[4])));
      }
      else if(op == "getdoubles") {
        vector<double> v = cfg(f[1]).getDoubles(f[2], parseDouble(f[3]), parseDouble(f[4]));
        r << "ok " << v.size();
        for(double x : v) r << " " << dbits(x);
      }
      else if(op == "getpairs") {
        vector<pair<int,int>> v = cfg(f[1]).getNonNegativeIntDashedPairs(f[2], parseInt(f[3]), parseInt(f[4]));
        r << "ok " << v.size();
        for(auto& p : v) r << " (" << p.first << "," << p.second << ")";
      }
      else if(op == "contains") {
        r << "ok " << (cfg(f[1]).contains(f[2]) ? 1 : 0);
      }
      else if(op == "containsany") {
        r << "ok " << (cfg(f[1]).containsAny(splitOn(f[2], ',')) ? 1 : 0);
      }
      else if(op == "firstfail") {
        r << "ok " << q(cfg(f[1]).firstFoundOrFail(splitOn(f[2], ',')));
      }
      else if(op == "firstempty") {
        r << "ok " << q(cfg(f[1]).firstFoundOrEmpty(splitOn(f[2], ',')));
      }
      else if(op == "overridekey") {
        cfg(f[1]).overrideKey(f[2], f[3]);
        r << "ok " << info(cfg(f[1]));
      }
      else if(op == "overridekeys") {
        cfg(f[1]).overrideKeys(parseKvs(f[2]));
        r << "ok " << info(cfg(f[1]));
      }
      else if(op == "overridekeysm") {
        vector<pair<set<string>,set<string>>> sets;
        for(const string& pr : splitOn(f[3], ';')) {
          vector<string> ab = splitOn(pr, '|');
          sets.push_back(make_pair(toSet(ab[0]), toSet(ab.size() > 1 ? ab[1] : string())));
        }
        cfg(f[1]).overrideKeys(parseKvs(f[2]), sets);
        r << "ok " << info(cfg(f[1]));
      }
      else if(op == "overridekeysfile") {
        cfg(f[1]).overrideKeys(f[2]);
        r << "ok " << info(cfg(f[1]));
      }
      else if(op == "parsecomma") {
        map<string,string> m = ConfigParser::parseCommaSeparated(f[1]);
        r << "ok " << m.size();
        for(auto& kv : m) r << " " << q(kv.first) << "=" << q(kv.second);
      }
      else if(op == "markused") {
        cfg(f[1]).markKeyUsed(f[2]);
        r << "ok " << info(cfg(f[1]));
      }
      else if(op == "markprefix") {
        cfg(f[1]).markAllKeysUsedWithPrefix(f[2]);
        r << "ok " << info(cfg(f[1]));
      }
      else if(op == "unsetused") {
        cfg(f[1]).unsetUsedKey(f[2]);
        r << "ok " << info(cfg(f[1]));
      }
      else if(op == "warn") {
        ostringstream o;
        cfg(f[1]).warnUnusedKeys(o, NULL);
        r << "ok " << q(o.str());
      }
      else if(op == "alias") {
        cfg(f[1]).applyAlias(f[2], f[3]);
        r << "ok " << info(cfg(f[1]));
      }
      else {
        cerr << "script error line " << lineno << ": unknown op " << op << endl;
        return 1;
      }
      cout << r.str();
    }
    catch(const ConfigParsingError& e) { cout << "err ConfigParsingError " << q(e.what()); }
    catch(const IOError& e) { cout << "err IOError " << q(e.what()); }
    catch(const StringError& e) { cout << "err StringError " << q(e.what()); }
    cout << "\n";
  }
  for(auto& kv : cfgs) delete kv.second;
  if(chdir("/") != 0) return 1;
  rmTree(scratch);
  cerr << "config_parser_oracle: " << nops << " ops" << endl;
  return 0;
}
